import{d as l,C as r,o as h,c as u,j as i,a as e,E as a,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第26章","description":"《中庸》第 26 章——至诚无息：不息则久久则征，徵则悠远博厚高明；博厚配地、高明配天、悠久无疆；其为物不贰，则其生物不测；纯亦不已。","frontmatter":{"title":"中庸·第26章","description":"《中庸》第 26 章——至诚无息：不息则久久则征，徵则悠远博厚高明；博厚配地、高明配天、悠久无疆；其为物不贰，则其生物不测；纯亦不已。","category":"guide","aliases":["第26章","中庸第26章","至诚无息"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-26.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-26.md","lastUpdated":1790316338000}'),d={name:"lizhimingde/sishu-wujing/zhongyong/chapter-26.md"},w=l({...d,setup(y){const o=[{id:"wuxi",label:"至诚无息 · 不息则久，久则征",showLabel:!0,sentences:[["故至诚",{text:"无息",glossary:"wuxi"},"。不息则",{text:"久",glossary:"jiu"},"，久则",{text:"征",glossary:"zheng"},"，征则",{text:"悠远",glossary:"youyuan"},"，悠远则",{text:"博厚",glossary:"bohou"},"，博厚则",{text:"高明",glossary:"gaoming"},"。"]],note:"「故至诚无息」——至诚之德，永不停息。「不息则久」：不停息便能长久；「久则征」（征＝验于外），「征则悠远，悠远则博厚，博厚则高明」——一层推一层，写至诚之德由内而外、由近及远的展开。"},{id:"peitiandi",label:"博厚所以载物 · 配地配天 · 悠久无疆",showLabel:!0,sentences:[["博厚，所以",{text:"载物",glossary:"zaiwu"},"也；高明，所以",{text:"覆物",glossary:"fuwu"},"也；悠久，所以成物也。博厚配地，高明配天，悠久",{text:"无疆",glossary:"wujiang"},"。"]],note:"「博厚，所以载物也；高明，所以覆物也；悠久，所以成物也」——博厚用来承载万物，高明用来覆盖万物，悠久用来成就万物。再配以天地：「博厚配地，高明配天，悠久无疆。」"},{id:"wuxiwei",label:"不见而章 · 不动而变 · 无为而成",showLabel:!0,sentences:[["如此者，",{text:"不见而章",glossary:"buxianzhang"},"，",{text:"不动而变",glossary:"budongbian"},"，",{text:"无为而成",glossary:"wuwei"},"。"],["天地之道，可一言而尽也：其为物",{text:"不贰",glossary:"buer"},"，则其生物",{text:"不测",glossary:"buce"},"。"]],note:"「如此者，不见而章，不动而变，无为而成」——不待显露而自彰著，不去推动而自变化，不作妄为而自成功。又：「天地之道，可一言而尽也：其为物不贰，则其生物不测」——天地之道一言可尽：其为物纯一不二，故其生物不可测度。"},{id:"tiandi",label:"天地之道：博厚高明悠久 · 天昭昭之多，地一撮土之多",showLabel:!0,sentences:[["天地之道：博也，厚也，高也，明也，悠也，久也。"],["今夫天，斯",{text:"昭昭",glossary:"zhaozhao"},"之多，及其无穷也，日月星辰系焉，万物覆焉。今夫地，一撮土之多，及其广厚，载华岳而不重，振河海而不泄，万物载焉。"]],note:"「天地之道：博也，厚也，高也，明也，悠也，久也」——天地之道，尽于这六字。以下用「积少成多」设喻：「今夫天，斯昭昭之多」，推到无穷，则「日月星辰系焉，万物覆焉」；「今夫地，一撮土之多」，推到广厚，则「载华岳而不重，振河海而不泄，万物载焉」。"},{id:"shanshui",label:"山一卷石 · 水一勺 · 及其广大不测",showLabel:!0,sentences:[["今夫山，一",{text:"卷石",glossary:"quanshi"},"之多，及其广大，草木生之，禽兽居之，宝藏兴焉。今夫水，一",{text:"勺",glossary:"shao"},"之多，及其不测，鼋鼍、蛟龙、鱼鳖生焉，货财殖焉。"]],note:"再以山水为喻：「今夫山，一卷石之多」（卷＝拳，拳头大的石头），及其广大，则「草木生之，禽兽居之，宝藏兴焉」；「今夫水，一勺之多」，及其不测，则「鼋鼍、蛟龙、鱼鳖生焉，货财殖焉」。皆言由微而著之理。"},{id:"buji",label:"维天之命，於穆不已 · 文王之德之纯",showLabel:!0,sentences:[["《诗》云：“维天之命，",{text:"於穆不已",glossary:"yumubuyi"},"！”盖曰天之所以为天也。“於乎不显！文王之德之纯！”盖曰文王之所以为文也，",{text:"纯亦不已",glossary:"chunyibuyi"},"。"]],note:"引《诗》「维天之命，於穆不已」——天命深远而不止息，这是说「天之所以为天」。又引「於乎不显！文王之德之纯」——何等光明！文王之德那样纯粹；这是说「文王之所以为文」——「纯亦不已」，纯一而不止息。全章以「不已」收束。"}],s=[{id:"wuxi",term:"无息",pinyin:"wú xī",meaning:"朱注：「既无虚假，自无间断。」不息，即不间断。"},{id:"jiu",term:"久",pinyin:"jiǔ",meaning:"朱注：「久，常于中也。」"},{id:"zheng",term:"征",pinyin:"zhēng",meaning:"朱注：「征，验于外也。」"},{id:"youyuan",term:"悠远",pinyin:"yōu yuǎn",meaning:"悠长而遥远。朱注：「存诸中者既久，则验于外者益悠远而无究矣。」"},{id:"bohou",term:"博厚",pinyin:"bó hòu",meaning:"广博而深厚。"},{id:"gaoming",term:"高明",pinyin:"gāo míng",meaning:"高大而光明。"},{id:"zaiwu",term:"载物",pinyin:"zài wù",meaning:"承载万物（地之德）。"},{id:"fuwu",term:"覆物",pinyin:"fù wù",meaning:"覆盖万物（天之德）。"},{id:"wujiang",term:"无疆",pinyin:"wú jiāng",meaning:"无边际。朱注：「此言圣人与天地同体。」"},{id:"buxianzhang",term:"不见而章",pinyin:"bù xiàn ér zhāng",meaning:"见：读 xiàn（显现）；章：同「彰」。不待显现而自然昭彰。"},{id:"budongbian",term:"不动而变",pinyin:"bù dòng ér biàn",meaning:"不须动作而变化自行。"},{id:"wuwei",term:"无为而成",pinyin:"wú wéi ér chéng",meaning:"不刻意作为而事成。"},{id:"buer",term:"不贰",pinyin:"bù èr",meaning:"不二、纯一。朱注：「不贰，所以诚也。」"},{id:"buce",term:"不测",pinyin:"bù cè",meaning:"不可测度。诚一故不息，生物之多莫知其所以然。"},{id:"zhaozhao",term:"昭昭",pinyin:"zhāo zhāo",meaning:"犹耿耿，一点小光明。朱注：「此指其一处而言之。」"},{id:"quanshi",term:"卷石",pinyin:"quán shí",meaning:"卷：读 quán，同「区」，一区之石。"},{id:"shao",term:"一勺",pinyin:"yī sháo",meaning:"一勺之水。"},{id:"yumubuyi",term:"於穆不已",pinyin:"wū mù bù yǐ",meaning:"《诗·周颂·维天之命》。於：叹辞，读 wū；穆：深远；不已：不间断。"},{id:"chunyibuyi",term:"纯亦不已",pinyin:"chún yì bù yǐ",meaning:"纯：纯一不杂。文王之德既纯且不间断。程子：「纯则无二无杂，不已则无间断先后。」"}];return(p,n)=>{const g=r("DaoTextReading"),t=r("DaoKeywordCards");return h(),u("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第26章",tabindex:"-1"},[e("中庸·第26章 "),i("a",{class:"header-anchor",href:"#中庸·第26章","aria-label":'Permalink to "中庸·第26章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,"第二十六章以「至诚无息」起头，一路推到「博厚配地、高明配天、悠久无疆」，再以天地、山川、一撮土、一勺水作喻，收在《诗》的「纯亦不已」。默认竹简沉浸通读；切「经典阅读」可点生词。",-1)),a(g,{colophon:"至诚无息 · 博厚高明悠久 · 纯亦不已",tone:"ink",sections:o,glossary:s,"default-mode":"slips","aria-label":"中庸·第26章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"无息",pinyin:["wú","xī"],meaning:"朱注：「既无虚假，自无间断。」不是用力不停，而是不假故不断。"},{term:"久",pinyin:["jiǔ"],meaning:"常于中。"},{term:"征",pinyin:["zhēng"],meaning:"验于外。"},{term:"悠远",pinyin:["yōu","yuǎn"],meaning:"中既久，则外益远。"},{term:"博厚",pinyin:["bó","hòu"],meaning:"配地，所以载物。"},{term:"高明",pinyin:["gāo","míng"],meaning:"配天，所以覆物。"},{term:"悠久",pinyin:["yōu","jiǔ"],meaning:"无疆，所以成物。"},{term:"不见而章",pinyin:["bù","xiàn","ér","zhāng"],meaning:"见读 xiàn，章同「彰」——不待显现而自然昭彰。"},{term:"不动而变",pinyin:["bù","dòng","ér","biàn"],meaning:"不须动作而变化自成。"},{term:"无为而成",pinyin:["wú","wéi","ér","chéng"],meaning:"不刻意作为而事成。"}]}),a(t,{items:[{term:"其为物不贰",pinyin:["qí","wéi","wù","bù","èr"],meaning:"不贰：不二、纯一。朱注：「不贰，所以诚也。」"},{term:"其生物不测",pinyin:["qí","shēng","wù","bù","cè"],meaning:"生成万物而不可测度。朱注：「诚故不息，而生物之多，有莫知其所以然者。」"},{term:"昭昭之多",pinyin:["zhāo","zhāo","zhī","duō"],meaning:"一点小光明。朱注：「此指其一处而言之。」"},{term:"一撮土",pinyin:["yī","cuō","tǔ"],meaning:"一把土。"},{term:"一卷石",pinyin:["yī","quán","shí"],meaning:"卷：读 quán，同「区」。一区之石。"},{term:"一勺",pinyin:["yī","sháo"],meaning:"一勺之水。朱注提醒「不以辞害意」——非谓天地山川实由积累而后大。"},{term:"於穆不已",pinyin:["wū","mù","bù","yǐ"],meaning:"《诗》句。於读 wū（叹辞），穆：深远——天之所以为天。"},{term:"纯亦不已",pinyin:["chún","yì","bù","yǐ"],meaning:"纯：纯一不杂——文王之所以为文。程子：「纯则无二无杂，不已则无间断先后。」"}]}),n[4]||(n[4]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>至诚无息 · 不息则久</strong>：所以至诚是不间断的。不间断就能长久，长久就能外显，外显就能悠远，悠远就能博厚，博厚就能高明。</p><p><strong>博厚所以载物 · 配地配天</strong>：博厚，是用来承载万物的；高明，是用来覆盖万物的；悠久，是用来成就万物的。博厚配地，高明配天，悠久无疆。</p><p><strong>不见而章 · 无为而成</strong>：这样的至诚，不待显现而自然昭彰，不须动作而变化自成，不刻意作为而事成。</p><p><strong>天地之道 · 昭昭之多</strong>：天地之道，可以用一句话说尽：它作为物是不二，那么它生成万物就不可测度。天地之道：博、厚、高、明、悠、久。如今看天，不过一点光明之多，到了无穷之处，日月星辰系于其上，万物被它覆盖；如今看地，不过一撮土之多，到了广厚之处，承载华山而不觉重，收拢河海而不漏泄，万物都被它承载。</p><p><strong>山一卷石 · 水一勺</strong>：如今看山，不过一区石头之多，到了广大之处，草木生长、禽兽居住、宝藏兴出；如今看水，不过一勺之多，到了不测之处，鼋鼍蛟龙鱼鳖都生长其中，财货繁殖起来。</p><p><strong>维天之命 · 纯亦不已</strong>：《诗经》说：「维天之命，於穆不已！」这是说天之所以为天。「於乎不显！文王之德之纯！」这是说文王之所以为文王——<strong>纯，也就永不停息</strong>。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第二十六章从「至诚无息」一路推演：</p><p><strong>无息 → 久 → 征 → 悠远 → 博厚 → 高明</strong>；再以「博厚配地、高明配天、悠久无疆」收束到「不见而章、不动而变、无为而成」。</p><p>然后转入天地：一句「<strong>其为物不贰，则其生物不测</strong>」，再以天（昭昭之多）、地（一撮土）、山（一卷石）、水（一勺）四喻，说「微末之积→无穷之用」。最后引《诗》落到「<strong>纯亦不已</strong>」。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「无息」不是用力不停</strong>：朱注说「既无虚假，自无间断」——<strong>不停，是因为不假</strong>。这比「坚持」深一层：虚假的东西必然断续，真实的东西自然连续。</li><li><strong>由内而外的次第</strong>：久（常于中）→ 征（验于外）→ 悠远 → 博厚 → 高明。<strong>内在的持久，最后变成外在的广大与光明。</strong></li><li><strong>「其为物不贰，则其生物不测」是全章的枢纽</strong>：不贰（诚一）是因，生物不测是果。<strong>专一，才有多产。</strong></li><li><strong>四个比喻讲的是「小处积起」</strong>：昭昭、撮土、卷石、勺水——都极小，却通到无穷。朱注特意提醒「不以辞害意」（天地山川非由积累而后大），意思是：<strong>这几句讲的是「由不贰不息以致盛大」之理，不是物理成因。</strong></li><li><strong>「纯亦不已」把天与文王并起来</strong>：天的品格是「不已」，文王的品格是「纯」——<strong>纯，所以不已</strong>。这与第 25 章「不诚无物」正好一正一反。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>「无息」的自查</strong>：我做的事情里，哪些是<strong>明知不实</strong>却还在撑？不实的事，撑不久（不诚无物 + 无息）。</li><li><strong>看次第</strong>：久 → 征 → 悠远 → 博厚 → 高明。想博厚高明，先问自己「久不久」。</li><li><strong>「不贰」</strong>：手上的事太杂，往往不是能力问题，是「贰」了。</li><li><strong>四喻的鼓励</strong>：起点小（昭昭、撮土、卷石、勺水）不是问题，<strong>关键是不已</strong>。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>至诚是<strong>不间断</strong>的。而不间断带来一串结果：长久 → 外显 → 悠远 → 博厚 → 高明。博厚足以载物（配地），高明足以覆物（配天），悠久则无疆——<strong>不待显现而昭彰，不须动作而变化，不刻意作为而成事。</strong></p><p>天地之道一句话说尽：<strong>它作为物不二，所以它生出的东西不可测度。</strong></p><p>接着是天、地、山、水四个比方：天不过一点光明，却能覆万物；地不过一撮土，却能载万物；山不过一区石，水不过一勺水，却生出草木禽兽、蛟龙鱼鳖。</p><p>最后引《诗经》把话挑明：天之所以为天，在「不已」；文王之所以为文王，在「纯」——<strong>纯，就是不已。</strong></p><p>所以这一章真正的题目不是「恒心」，而是：<strong>真实，所以不断；不二，所以无穷。</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「既无虚假，自无间断」——我有没有在硬撑一件心里知道不实的事？</li><li>久 → 征 → 悠远 → 博厚 → 高明——我想要「博厚高明」，可我「久」了吗？</li><li>「其为物不贰，则其生物不测」——我手上的事，是不是「贰」了？</li><li>昭昭／撮土／卷石／勺水——起点这么小，我信「不已」的力量吗？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-25">中庸·第25章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-27">中庸·第27章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',29))])}}});export{c as __pageData,w as default};
